          <p v-else-if="!acceptance.current" class="vf-warning" role="status">\u9A8C\u6536\u5C1A\u672A\u8986\u76D6\u5F53\u524D\u65E5\u6863\uFF0C\u4EE5\u4E0B\u4E3A\u6700\u8FD1\u4E00\u6B21\u9A8C\u6536\u8BB0\u5F55</p>
